    biography: "Rokas Peciulaitis is Founder and Managing Partner of Contrarian Ventures, the Vilnius-headquartered climate tech fund he started in 2017. His firm bio states he began his career as an inflation trader at Bank of America Merrill Lynch in 2016 before moving into climate investing. He made first institutional investments in PVcase, BeZero Carbon and Ember. He co-founded and leads the firm's platform initiatives, including the Energy Tech Summit, Climate 50, Climate Brick and a European WinterFest edition. He holds an M.A. in Economics from the University of Glasgow, studied at UC Santa Barbara, completed the Harvard Business School Executive Program in PE & VC, and is a Kauffman Fellow (Class 25).",
