    careerTimeline: [{ year: 1997, event: "Co-founded the firm that is now Headline" }],
    biography: "Thomas Gieselmann is a Founding Partner of Headline, based in San Francisco. He started a paper publishing and distribution company at fourteen, and later founded and operated AOL.de in Germany before co-founding the firm in 1997. He invests in developer tools, open source, infrastructure software, cloud, AI and fintech, favouring non-linear products with exponential market disruption potential. His portfolio includes NGINX (acquired by F5 Networks), Segment (acquired by Twilio), GoToMeeting (acquired by Citrix), Data.ai (acquired by Sensor Tower), Nom Nom (acquired by Mars Petcare) and SEMrush. He says the most important trait in a founder is agility.",
