    biography: "Alex Shmulovich is a Partner at Viola Ventures, which he joined in 2023, and leads the fund's investments in deep tech and AI startups. He was previously a Project Leader at Boston Consulting Group, working across the firm's financial institutions and growth tech practices, and before that worked in PwC's strategy and valuations group on M&A and IPO advisory. He also co-founded and served on the board of a bootstrapped edtech startup. His active investments at Viola Ventures include Tenna, Vimi and Impala AI. He holds a BA in Accounting and an LLB from the College of Management and an MBA from INSEAD.",
